        new(() => new JsonSerializerSettings 
        { 
            NullValueHandling = NullValueHandling.Ignore,
            DateFormatHandling = DateFormatHandling.IsoDateFormat
        });

    // Fallback for complex/dynamic scenarios
    public static T DeserializeComplex<T>(string json) 
        => JsonConvert.DeserializeObject<T>(json, _newtonsoftSettings.Value);
