public partial class MyContext : JsonSerializerContext { }

var options = new JsonSerializerOptions
{
    TypeInfoResolver = MyContext.Default // Zero-reflection path
};

// 2. Improved internal pooling for large JSON documents
// 3. Faster UTF-8 parsing without UTF-8→UTF-16 conversion overhead
// 4. Optimized escape/unescape sequences
// 5. Better handling of polymorphic types via JsonDerivedType
```

