        Console.WriteLine($"STJ Deserialize: {stjDeserializeSw.ElapsedMilliseconds} ms " +
                          $"({stjDeserializeSw.ElapsedMilliseconds / iterations:F2} µs/op)");
        Console.WriteLine($"NJ  Deserialize: {njDeserializeSw.ElapsedMilliseconds} ms " +
                          $"({njDeserializeSw.ElapsedMilliseconds / iterations:F2} µs/op)");
        Console.WriteLine($"STJ vs NJ Serialize Speedup:     {(double)njSerializeSw.ElapsedMilliseconds / stjSerializeSw.ElapsedMilliseconds:F2}x");
        Console.WriteLine($"STJ vs NJ Deserialize Speedup:   {(double)njDeserializeSw.ElapsedMilliseconds / stjDeserializeSw.ElapsedMilliseconds:F2}x");
        Console.WriteLine();
    }

    private static ComplexObject GenerateComplexGraph(int depth, int listSize)
    {
        var obj = new ComplexObject
        {
            Id = 1,
            Name = "Test Object",
            CreatedAt = DateTime.UtcNow,
            Price = 99.99m,
            BinaryData = new byte[1024],
            OptionalReference = null
        };

        Random rng = new(42);
        rng.NextBytes(obj.BinaryData);

        for (int i = 0; i < listSize; i++)
        {
            var nested = new NestedObject
            {
                GuidValue = Guid.NewGuid(),
                Description = $"Item {i}"
            };

            for (int j = 0; j < Math.Min(listSize / 2, 5); j++)
            {
                nested.Tags.Add(new Tag
                {
                    Key = $"tag_{j}",
                    Value = $"value_{rng.Next(1000)}"
                });
            }

            nested.Categories = Enumerable.Range(0, 3).Select(_ => $"cat_{rng.Next(100)}");
            obj.Children.Add(nested);
        }

        // Add dictionary entries
        for (int i = 0; i < listSize; i++)
        {
            obj.Attributes[$"attr_{i}"] = new Metadata
            {
                Type = "string",
                Data = $"data_{i}_{rng.Next(10000)}"
            };
        }

        return obj;
    }
}
```

