    // Helper to generate test data
    private static ComplexObject GenerateComplexObject(int depth, int breadth)
    {
        var obj = new ComplexObject();
        for (int i = 0; i < breadth; i++)
        {
            obj.Children.Add(BuildChild(depth, breadth));
        }
        for (int i = 0; i < breadth * 2; i++)
        {
            obj.Metadata[$"key_{i}"] = new Metadata
            {
                Key = $"meta_{i}",
                Value = i % 2 == 0 ? i : "string_value",
                IsActive = i % 3 != 0
            };
