            for (int i = 0; i < breadth; i++)
            {
                child.SubChildren.Add(BuildChild(remainingDepth - 1, Math.Max(1, breadth / 2)));
            }
        }
        child.NullableValue = remainingDepth % 2 == 0 ? 99.99m : null;
        return child;
    }
